/**
 * DS Compass — PatternFly 6 Compass under the Golden Passport dials.
 * Thin wrapper: the dial CSS (src/styles) already brands it; add DS
 * defaults here when the design system diverges from stock PF6.
 * Generated by scripts/gen-pf-wrappers.mjs — hand-maintained after that.
 */
import { Compass as PFCompass } from "@patternfly/react-core";
import type { ComponentProps } from "react";

export type CompassProps = Omit<ComponentProps<typeof PFCompass>, "ref">;

export function Compass(props: CompassProps) {
  return <PFCompass {...props} />;
}

export {
  CompassContent,
  CompassHeader,
  CompassHero,
  CompassMainHeader,
  CompassMainHeaderContent,
  CompassMessageBar,
  CompassNavContent,
  CompassNavHome,
  CompassNavMain,
  CompassNavSearch,
} from "@patternfly/react-core";
